/** FFmpeg command builders — each returns an array of CLI args */

export function resizeCmd(inputFile, outputFile, width, height) {
  return [
    '-i', inputFile,
    '-vf', `scale=${width}:${height}:flags=lanczos`,
    '-y', outputFile,
  ];
}

export function cropCmd(inputFile, outputFile, w, h, x, y) {
  return [
    '-i', inputFile,
    '-vf', `crop=${w}:${h}:${x}:${y}`,
    '-y', outputFile,
  ];
}

/**
 * Compress via two-pass palette optimization.
 * Returns [pass1Args, pass2Args] — caller must run both sequentially.
 */
export function compressCmds(inputFile, outputFile, { colors = 256, fps = null } = {}) {
  const filters = [];
  if (fps) filters.push(`fps=${fps}`);

  const pass1Filters = [...filters, `palettegen=max_colors=${colors}:stats_mode=diff`].join(',');
  const pass2Filters = [...filters, `paletteuse=dither=bayer:bayer_scale=5`].join(',');

  const pass1 = ['-i', inputFile, '-vf', pass1Filters, '-y', 'palette.png'];
  const pass2 = ['-i', inputFile, '-i', 'palette.png', '-lavfi', pass2Filters, '-y', outputFile];
  return [pass1, pass2];
}

export function speedCmd(inputFile, outputFile, speed) {
  const pts = 1 / speed;
  return [
    '-i', inputFile,
    '-vf', `setpts=${pts.toFixed(4)}*PTS`,
    '-y', outputFile,
  ];
}

export function trimCmd(inputFile, outputFile, startTime, duration) {
  const args = ['-i', inputFile];
  if (startTime > 0) args.push('-ss', String(startTime));
  if (duration > 0) args.push('-t', String(duration));
  args.push('-y', outputFile);
  return args;
}

export function reverseCmd(inputFile, outputFile) {
  return [
    '-i', inputFile,
    '-vf', 'reverse',
    '-y', outputFile,
  ];
}

export function filterCmd(inputFile, outputFile, { brightness = 0, contrast = 1, saturation = 1, grayscale = false }) {
  const filters = [];
  if (grayscale) {
    filters.push('hue=s=0');
  }
  if (brightness !== 0 || contrast !== 1 || saturation !== 1) {
    filters.push(`eq=brightness=${brightness}:contrast=${contrast}:saturation=${saturation}`);
  }
  if (filters.length === 0) filters.push('null');
  return [
    '-i', inputFile,
    '-vf', filters.join(','),
    '-y', outputFile,
  ];
}

export function extractFramesCmd(inputFile, outputPattern) {
  return [
    '-i', inputFile,
    '-vsync', '0',
    outputPattern,
  ];
}

/** Assemble numbered PNG frames into a GIF with an optimized single-pass palette */
export function assembleFramesCmd(inputPattern, outputFile, fps = 10) {
  return [
    '-framerate', String(fps),
    '-i', inputPattern,
    '-filter_complex', 'split[a][b];[a]palettegen=stats_mode=diff[p];[b][p]paletteuse=dither=bayer:bayer_scale=5',
    '-y', outputFile,
  ];
}

/**
 * Combined resize + compress for Slack emoji preset.
 * Returns [pass1Args, pass2Args] — caller must run both sequentially.
 */
export function slackEmojiCmds(inputFile, outputFile, { size = 128, colors = 256, fps = 15 }) {
  const preprocess = [
    `crop=min(iw\\,ih):min(iw\\,ih):(iw-min(iw\\,ih))/2:(ih-min(iw\\,ih))/2`,
    `scale=${size}:${size}:flags=lanczos`,
  ];
  if (fps) preprocess.push(`fps=${fps}`);

  const pass1Filters = [...preprocess, `palettegen=max_colors=${colors}:stats_mode=diff`].join(',');
  const pass2Filters = [...preprocess, `paletteuse=dither=bayer:bayer_scale=5`].join(',');

  const pass1 = ['-i', inputFile, '-vf', pass1Filters, '-y', 'palette.png'];
  const pass2 = ['-i', inputFile, '-i', 'palette.png', '-lavfi', pass2Filters, '-y', outputFile];
  return [pass1, pass2];
}
import { reverseCmd } from '../ffmpeg/commands.js';
import { registerTool } from '../components/toolbar.js';
import { applyEdit } from './shared.js';
import * as player from '../components/player.js';
import { panelHeader, button, note } from '../ui/components.js';

const tool = {
  id: 'reverse',
  label: 'Reverse',
  iconName: 'reverse',
  hue: 'cyan',
  hint: 'Play it backwards.',
  render: renderReverse,
  exit: () => player.setReverse(false),
};
registerTool(tool);

function renderReverse(panel) {
  const canPreview = player.canReverse();
  panel.innerHTML = `
    ${panelHeader(tool)}
    <div class="space-y-4">
      ${canPreview ? `
        <label class="flex items-center justify-between gap-3 p-3 rounded-2xl bg-surface-2 cursor-pointer">
          <span class="text-sm font-bold">Preview reversed</span>
          <input id="reverse-preview" type="checkbox" class="switch" checked />
        </label>` : ''}
      ${button({ id: 'reverse-apply', label: 'Reverse GIF', iconName: 'rewind', variant: 'primary', block: true })}
      ${canPreview ? '' : note('A live preview isn\u2019t available for this GIF. It\u2019s too large to hold in memory, or this browser can\u2019t decode it frame by frame.')}
    </div>
  `;

  const toggle = document.getElementById('reverse-preview');
  if (toggle) {
    player.setReverse(true);
    toggle.addEventListener('change', () => player.setReverse(toggle.checked));
  }

  document.getElementById('reverse-apply').addEventListener('click', () => {
    applyEdit({
      label: 'Reverse',
      busy: 'Reversing…',
      passes: [reverseCmd('input.gif', 'output.gif')],
      success: () => 'Reversed! It now plays backwards.',
    });
  });
}
import { getState, setState, subscribe, commit } from '../utils/state.js';
import { writeFile, readFile, runFFmpeg, deleteFile, initFFmpeg, onProgress } from '../ffmpeg/engine.js';
import { showToast } from '../components/toast.js';

let jobText = '';

function setJobProgress(ratio, sub = '') {
  const bar = document.getElementById('job-bar');
  const valid = Number.isFinite(ratio) && ratio > 0 && ratio <= 1;
  bar.classList.toggle('progress-indeterminate', !valid);
  bar.style.width = valid ? `${Math.round(ratio * 100)}%` : '';
  document.getElementById('job-sub').textContent = sub;
}

export function showProcessing(text = 'Working…') {
  console.log(`[Processing] Start: ${text}`);
  jobText = text;
  setState({ processing: true });
  document.getElementById('job-overlay').classList.remove('hidden');
  document.getElementById('job-text').textContent = text;
  setJobProgress(null);
}

export function hideProcessing() {
  console.log('[Processing] Done');
  setState({ processing: false });
  onProgress(null);
  document.getElementById('job-overlay').classList.add('hidden');
}

/** While a job waits on the engine, mirror the engine's download progress in the overlay */
export function initJobOverlay() {
  subscribe('engine', (engine) => {
    if (!getState().processing) return;
    if (engine.status === 'loading') {
      document.getElementById('job-text').textContent = 'Warming up the engine…';
      setJobProgress(engine.pct / 100, engine.text);
    } else if (engine.status === 'ready') {
      document.getElementById('job-text').textContent = jobText;
      setJobProgress(null);
    }
  });
}

/**
 * Run an async FFmpeg job behind the stage overlay. Errors become a toast.
 * Returns the job's result, or undefined if it failed or another job was running.
 */
export async function runJob(text, fn) {
  if (getState().processing) return undefined;
  showProcessing(text);
  try {
    await initFFmpeg();
    document.getElementById('job-text').textContent = text;
    return await fn();
  } catch (err) {
    console.error(`[Job] ${text} failed:`, err);
    showToast(`${text.replace(/…$/, '')} failed: ${err?.message || err}`, 'error', 6000);
    return undefined;
  } finally {
    hideProcessing();
  }
}

/**
 * Write `gif` as input.gif, run each FFmpeg pass, and return output.gif's bytes.
 * Two-pass commands (palettegen → paletteuse) write palette.png in between.
 */
export async function transformGif(gif, passes) {
  await writeFile('input.gif', gif);
  try {
    for (let i = 0; i < passes.length; i++) {
      onProgress((p) => setJobProgress(
        (i + Math.min(1, Math.max(0, p))) / passes.length,
        passes.length > 1 ? `Pass ${i + 1} of ${passes.length}` : '',
      ));
      await runFFmpeg(passes[i]);
    }
    return await readFile('output.gif');
  } finally {
    onProgress(null);
    await deleteFile('input.gif');
    await deleteFile('output.gif');
    await deleteFile('palette.png');
  }
}

/**
 * The common tool flow: transform the current GIF, commit it to history, toast.
 * `passes` is an array of FFmpeg arg arrays reading input.gif → output.gif.
 */
export function applyEdit({ label, busy, passes, success }) {
  return runJob(busy, async () => {
    const before = getState().currentGif;
    const result = await transformGif(before, passes);
    commit(label, result);
    showToast(success ? success(result, before) : `${label} applied`, 'success');
    return result;
  });
}
import { FFmpeg } from '@ffmpeg/ffmpeg';
import { toBlobURL } from '@ffmpeg/util';
import { setState } from '../utils/state.js';

const DB_NAME = 'gif-editor-cache';
const STORE_NAME = 'ffmpeg';
const CORE_VERSION = '0.12.6';
const BASE_URL = `https://unpkg.com/@ffmpeg/core@${CORE_VERSION}/dist/esm`;

let ffmpeg = null;
/** @type {Promise|null} in-flight load, shared by concurrent callers */
let loadPromise = null;
/** @type {((ratio: number) => void)|null} */
let progressListener = null;

function openDB() {
  return new Promise((resolve, reject) => {
    const req = indexedDB.open(DB_NAME, 1);
    req.onupgradeneeded = () => req.result.createObjectStore(STORE_NAME);
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });
}

async function getCached(key) {
  try {
    const db = await openDB();
    return await new Promise((resolve) => {
      const tx = db.transaction(STORE_NAME, 'readonly');
      const req = tx.objectStore(STORE_NAME).get(key);
      req.onsuccess = () => resolve(req.result ?? null);
      req.onerror = () => resolve(null);
    });
  } catch {
    return null;
  }
}

async function setCached(key, value) {
  try {
    const db = await openDB();
    const tx = db.transaction(STORE_NAME, 'readwrite');
    tx.objectStore(STORE_NAME).put(value, key);
    await new Promise((resolve, reject) => {
      tx.oncomplete = resolve;
      tx.onerror = reject;
    });
  } catch {
    // cache failure is non-fatal
  }
}

function updateProgress(pct, text) {
  setState({ engine: { status: 'loading', pct: Math.min(100, pct), text } });
}

async function fetchWithProgress(url, cacheKey) {
  // Check IndexedDB cache first
  const cached = await getCached(cacheKey);
  if (cached?.version === CORE_VERSION && cached?.data) {
    console.log('[FFmpeg] Loaded WASM from IndexedDB cache');
    return URL.createObjectURL(new Blob([cached.data], { type: 'application/wasm' }));
  }
  console.log('[FFmpeg] Cache miss, downloading WASM from', url);

  const response = await fetch(url);
  const contentLength = Number(response.headers.get('content-length')) || 0;
  const reader = response.body.getReader();
  const chunks = [];
  let received = 0;

  while (true) {
    const { done, value } = await reader.read();
    if (done) break;
    chunks.push(value);
    received += value.length;
    if (contentLength > 0) {
      // Download is the bulk of the work: map it onto 5–90%
      const pct = 5 + Math.round((received / contentLength) * 85);
      const mb = (received / 1024 / 1024).toFixed(1);
      const totalMb = (contentLength / 1024 / 1024).toFixed(1);
      updateProgress(pct, `Downloading engine… ${mb} / ${totalMb} MB`);
    }
  }

  const data = new Uint8Array(received);
  let offset = 0;
  for (const chunk of chunks) {
    data.set(chunk, offset);
    offset += chunk.length;
  }

  // Store in IndexedDB for next time
  console.log(`[FFmpeg] Download complete: ${(received / 1024 / 1024).toFixed(1)} MB, caching to IndexedDB`);
  await setCached(cacheKey, { version: CORE_VERSION, data });

  return URL.createObjectURL(new Blob([data], { type: 'application/wasm' }));
}

async function load() {
  console.log('[FFmpeg] Initializing FFmpeg.wasm…');
  updateProgress(0, 'Warming up…');

  const instance = new FFmpeg();
  instance.on('progress', ({ progress }) => progressListener?.(progress));

  updateProgress(5, 'Loading core…');
  const coreURL = await toBlobURL(`${BASE_URL}/ffmpeg-core.js`, 'text/javascript');
  const wasmURL = await fetchWithProgress(`${BASE_URL}/ffmpeg-core.wasm`, 'ffmpeg-core-wasm');

  updateProgress(92, 'Starting engine…');
  await instance.load({ coreURL, wasmURL });

  ffmpeg = instance;
  setState({ engine: { status: 'ready', pct: 100, text: 'Engine ready' } });
  console.log('[FFmpeg] Engine loaded and ready');
  return ffmpeg;
}

/**
 * Load the engine once. Concurrent callers (background preload + a tool click)
 * share the same promise; a failed load can be retried by calling again.
 */
export function initFFmpeg() {
  if (ffmpeg) return Promise.resolve(ffmpeg);
  if (!loadPromise) {
    loadPromise = load().catch((err) => {
      console.error('[FFmpeg] Load failed:', err);
      loadPromise = null;
      setState({ engine: { status: 'error', pct: 0, text: 'Engine failed to load' } });
      throw err;
    });
  }
  return loadPromise;
}

/** Receive 0–1 progress for the running exec (null to stop listening) */
export function onProgress(cb) {
  progressListener = cb;
}

export async function runFFmpeg(args) {
  console.log('[FFmpeg] exec:', args.join(' '));
  const ff = await initFFmpeg();
  const start = performance.now();
  await ff.exec(args);
  console.log(`[FFmpeg] exec done in ${(performance.now() - start).toFixed(0)}ms`);
}

export async function writeFile(name, data) {
  console.log(`[FFmpeg] writeFile: ${name} (${(data.byteLength / 1024).toFixed(1)} KB)`);
  const ff = await initFFmpeg();
  // Always copy to prevent the original ArrayBuffer from being detached
  const copy = new Uint8Array(data);
  await ff.writeFile(name, copy);
}

export async function readFile(name) {
  const ff = await initFFmpeg();
  const data = await ff.readFile(name);
  console.log(`[FFmpeg] readFile: ${name} (${(data.byteLength / 1024).toFixed(1)} KB)`);
  return data;
}

export async function deleteFile(name) {
  const ff = await initFFmpeg();
  try {
    await ff.deleteFile(name);
  } catch {
    // ignore if file doesn't exist
  }
}

export function isLoaded() {
  return ffmpeg !== null;
}

