const path = require('path');
const createFFmpegCore = require(path.join(__dirname, 'core/package/dist/umd/ffmpeg-core.js'));
(async () => {
  const neu = await import(process.argv[2]);
  const old = await import(path.join(__dirname, 'old-commands.mjs'));
  let log = [];
  const core = await createFFmpegCore({ print: () => {}, printErr: (s) => log.push(s) });
  const run = (args) => { log = []; core.exec(...args); const r = core.ret; core.reset(); if (r !== 0) throw new Error(log.slice(-5).join('\n')); };
  const kb = (n) => (n / 1024).toFixed(0).padStart(5) + 'KB';
  // count frames + frames-with-transparency via decoding to rawvideo rgba
  const probe = (f) => {
    run(['-i', f, '-f', 'framecrc', '-y', 'crc.txt']);
    const lines = new TextDecoder().decode(core.FS.readFile('crc.txt')).split('\n').filter((l) => /^\d/.test(l));
    const pts = lines.map((l) => +l.split(',')[2]);
    run(['-i', f, '-vf', 'alphaextract,negate,signalstats,metadata=print:key=lavfi.signalstats.YMAX:file=a.txt', '-f', 'null', '-']);
    const amax = new TextDecoder().decode(core.FS.readFile('a.txt')).match(/YMAX=(\d+)/g)?.map((s) => +s.slice(5)) ?? [];
    return `${String(lines.length).padStart(3)}fr dur=${(pts.at(-1) / 100).toFixed(2)}s transparent=${amax.some((v) => v > 128) ? 'yes' : 'no '}`;
  };
  for (const src of ['src.gif', 'alpha.gif']) {
    const data = require('fs').readFileSync(path.join(__dirname, src.replace('.gif', '') === 'src' ? 'out-src-reverse.gif' : 'out-alpha-reverse.gif'));
    core.FS.writeFile('orig.gif', data);
    console.log(`\n== ${src} ${kb(data.byteLength)} ${probe('orig.gif')}`);
    const mk = (c) => ({
      reverse: c.reverseCmd ? [c.reverseCmd('input.gif', 'output.gif')] : c.reverseCmds('input.gif', 'output.gif'),
      speed2x: c.speedCmd ? [c.speedCmd('input.gif', 'output.gif', 2)] : c.speedCmds('input.gif', 'output.gif', 2),
      speed05: c.speedCmd ? [c.speedCmd('input.gif', 'output.gif', 0.5)] : c.speedCmds('input.gif', 'output.gif', 0.5),
      trim: c.trimCmd ? [c.trimCmd('input.gif', 'output.gif', 0.9995, 1.9995)] : c.trimCmds('input.gif', 'output.gif', 0.9995, 1.9995),
      resize: c.resizeCmd ? [c.resizeCmd('input.gif', 'output.gif', 240, -1)] : c.resizeCmds('input.gif', 'output.gif', 240, -1),
      crop: c.cropCmd ? [c.cropCmd('input.gif', 'output.gif', 100, 80, 10, 10)] : c.cropCmds('input.gif', 'output.gif', 100, 80, 10, 10),
      filter: c.filterCmd ? [c.filterCmd('input.gif', 'output.gif', { grayscale: true })] : c.filterCmds('input.gif', 'output.gif', { grayscale: true }),
    });
    const O = mk(old), N = mk(neu);
    for (const k of Object.keys(O)) {
      const res = [];
      for (const p of [O[k], N[k]]) {
        core.FS.writeFile('input.gif', data);
        for (const a of p) run(a);
        res.push(`${kb(core.FS.readFile('output.gif').byteLength)} ${probe('output.gif')}`);
      }
      console.log(`${k.padEnd(8)} OLD ${res[0]} | NEW ${res[1]}`);
    }
  }
})().catch((e) => { console.error(e.message); process.exit(1); });
EOF
