    console.log(f);
    const r = await page.evaluate(async (b64) => {
      const { optimizeGif } = await import('/src/gifsicle/optimize.js');
      const bytes = Uint8Array.from(atob(b64), (c) => c.charCodeAt(0));
      const out = {};
      for (const lossy of [0, 40, 100]) {
        const res = await optimizeGif(bytes, { lossy });
        // decode with the browser to make sure the output is valid and has the same frame count
        const dec = new ImageDecoder({ data: res, type: 'image/gif' });
        await dec.tracks.ready;
        out[lossy] = `${(res.byteLength / 1024).toFixed(0)}KB frames=${dec.tracks.selectedTrack.frameCount}`;
      }
      const dec = new ImageDecoder({ data: bytes, type: 'image/gif' }); await dec.tracks.ready;
      return { in: `${(bytes.byteLength / 1024).toFixed(0)}KB frames=${dec.tracks.selectedTrack.frameCount}`, ...out };
    }, b64);
    console.log('  ', JSON.stringify(r));
  }
  // guard: garbage input must come back unchanged, not throw
  const g = await page.evaluate(async () => {
    const { optimizeGif } = await import('/src/gifsicle/optimize.js');
    const junk = new Uint8Array([1, 2, 3, 4]);
