cd $CLAUDE_JOB_DIR/tmp && cat > e2e.cjs <<'EOF'
const { chromium } = require('playwright-core');
const path = require('path');
(async () => {
  const browser = await chromium.launch({ channel: 'chrome', headless: true });
  const page = await browser.newPage();
  page.on('console', (m) => /readFile: output|Gifsicle|failed|Error/i.test(m.text()) && console.log('  console:', m.text()));
  page.on('pageerror', (e) => console.log('  PAGEERROR', e.message));
  await page.goto('http://localhost:5191/gif-editor/');
  await page.setInputFiles('#file-input', path.join(__dirname, 'out-src-reverse.gif'));
  const toast = async () => {
    await page.waitForSelector('#job-overlay.hidden', { state: 'attached', timeout: 240000 });
    await page.waitForTimeout(300);
    return page.evaluate(() => [...document.querySelectorAll('[role=status], .toast, #toast-root *')].map((e) => e.textContent.trim()).filter(Boolean).pop());
  };
  const steps = [
    ['reverse', async () => page.click('#reverse-apply')],
    ['compress', async () => { await page.click('#compress-presets [data-value="tiny"], #compress-presets button:has-text("Tiny")'); await page.click('#compress-apply'); }],
  ];
  for (const [tool, act] of steps) {
    await page.click(`#tool-rail [data-tool="${tool}"]`);
    await page.waitForTimeout(300);
    console.log(`== ${tool}`);
    await act();
    await page.waitForSelector('#job-overlay:not(.hidden)', { timeout: 10000 }).catch(() => {});
    console.log('  toast:', await toast());
  }
  if (await page.evaluate(() => document.getElementById('compress-lossy-val')?.textContent)) console.log('  lossy slider after Tiny preset:', await page.textContent('#compress-lossy-val'));
  await browser.close();
})().catch((e) => { console.error(e); process.exit(1); });
EOF
